import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const read=p=>fs.readFileSync(new URL(p,import.meta.url),'utf8');
const context=vm.createContext({});
vm.runInContext(read('./dist/renal-math.js'),context);
const calc=vm.runInContext('RenalMath',context);
const input={age:60,sex:'male',creatinine:1,unit:'mgdl',equation:'ckdepi2021',context:'stable',deindex:false};
const result=overrides=>calc.compute({...input,...overrides});
// Published NKF Table S1 verification values, not outputs generated by this app.
// https://www.kidney.org/recommendations-implementing-ckd-epi-2021-race-free-egfr-calculation-guidelines-clinical
const published=[[18,'male',0.90,127],[18,'male',0.91,125],[18,'female',0.70,128],[18,'female',0.71,126],[90,'male',0.50,97],[90,'male',1.50,44],[90,'female',0.50,89],[90,'female',1.50,33]];
for(const [age,sex,creatinine,expected] of published){
  const mg=result({age,sex,creatinine});assert.equal(mg.ok,true);assert.equal(Math.round(mg.indexed),expected);
  const si=result({age,sex,creatinine:creatinine*88.4,unit:'umol'});assert.equal(si.ok,true);assert.ok(Math.abs(si.indexed-mg.indexed)<1e-10);
}
// Independent scalar evaluation of the published IDMS MDRD equation (no race multiplier).
for(const [age,sex,creatinine,expected] of [[60,'male',1,76.22077229137905],[60,'female',1,56.555813040203255],[40,'male',2,37.190434769827505],[40,'female',2,27.59530259921201],[90,'male',1.5,43.96605575559401],[90,'female',1.5,32.62281337065076]]){
  const a=result({age,sex,creatinine,equation:'mdrd'});assert.ok(Math.abs(a.indexed-expected)<1e-10);assert.match(a.warnings.join(' '),/Legacy MDRD.*race multiplier.*omitted/);
  assert.ok(Math.abs(result({age,sex,creatinine:creatinine*88.4,unit:'umol',equation:'mdrd'}).indexed-expected)<1e-10);
}
for(const [sex,knot] of [['male',0.9],['female',0.7]]){
  const left=result({sex,creatinine:knot-1e-10}).indexed,right=result({sex,creatinine:knot+1e-10}).indexed;
  assert.ok(Math.abs(left-right)<1e-6,'Equation must be continuous across the creatinine splice');
}
const bsa=result({deindex:true,height:180,weight:80});assert.equal(bsa.bsa,2);assert.ok(Math.abs(bsa.absolute-bsa.indexed*2/1.73)<1e-12);
assert.equal(result({deindex:false,height:0,weight:0}).absolute,null);
for(const overrides of [{age:''},{age:0},{age:17},{age:121},{age:Infinity},{sex:''},{sex:'x'},{creatinine:''},{creatinine:0},{creatinine:-1},{creatinine:NaN},{creatinine:Infinity},{creatinine:'<0.1'},{unit:'mg/L'},{context:''},{context:'aki'},{context:'dialysis'},{context:'pregnancy'},{equation:'2009'},{deindex:true,height:'',weight:70},{deindex:true,height:170,weight:''},{deindex:true,height:49,weight:70},{deindex:true,height:170,weight:501}]){
  const x=result(overrides);assert.equal(x.ok,false,JSON.stringify(overrides));assert.equal('indexed' in x,false,'No number may survive validation failure');assert.ok(x.message);
}
assert.equal(result({age:18}).ok,true);assert.equal(result({age:120}).ok,true);
assert.equal(result({creatinine:0.15}).warnings.length,1);
const data=JSON.parse(read('./dist/database.json')),old=JSON.parse(read('./baseline_v08.json'));
assert.equal(data.version,'0.19.0');assert.equal(data.clinicalDataVersion,'0.19.0');
assert.deepEqual(data.calculatorSources.slice(0,6),old.calculatorSources);assert.deepEqual(data.sharedGuidance,old.sharedGuidance);
assert.equal(data.calculatorSources.length,15);assert.ok(data.calculatorSources.slice(6).every(s=>/^https:\/\//.test(s.url)));
const html=read('./dist/index.html');assert.ok(html.includes(read('./dist/renal-math.js')));assert.ok(html.includes(read('./dist/calculator.js')));assert.match(html,/id="calculator"/);
assert.ok(!/localStorage|sessionStorage|fetch\s*\(|downloadText|setHash|location\./.test(read('./dist/calculator.js')),'Calculator values must not be persisted, exported or sent');
assert.match(read('./dist/app.js'),/!\$\('#calculator'\)\.open/,'Drug-search shortcut must not run over the calculator');
// Contrast-associated AKI: Mehran (2004) points and bands, ACR–NKF IV thresholds.
vm.runInContext(read('./dist/contrast-math.js')+';this.CM=ContrastMath;',context);const CM=context.CM;
const m=o=>CM.mehran({egfr:80,volume:0,...o});
assert.equal(m({}).score,0);assert.equal(m({}).band.cin,'7.5%');
assert.equal(m({hypotension:true}).score,5);assert.equal(m({hypotension:true}).band.label,'Low');
assert.equal(m({hypotension:true,iabp:true}).score,10);assert.equal(m({hypotension:true,iabp:true}).band.dialysis,'0.12%');
assert.equal(m({hypotension:true,iabp:true,anaemia:true}).score,13);assert.equal(m({hypotension:true,iabp:true,anaemia:true}).band.cin,'26.1%');
assert.equal(m({hypotension:true,iabp:true,chf:true,age75:true,anaemia:true,diabetes:true,volume:300,egfr:15}).score,34);assert.equal(m({chf:true,iabp:true,hypotension:true,anaemia:true}).band.label,'Very high');
for(const [egfr,p] of [[60,0],[59.9,2],[40,2],[39.9,4],[20,4],[19.9,6]])assert.equal(m({egfr}).score,p,`eGFR ${egfr}`);
for(const [volume,p] of [[99,0],[100,1],[250,2],[400,4]])assert.equal(m({volume}).score,p,`volume ${volume}`);
for(const bad of [{egfr:''},{egfr:0},{egfr:250},{volume:-1},{volume:''},{volume:3000}]){const x=m(bad);assert.equal(x.ok,false);assert.equal('score' in x,false);}
const iv=o=>CM.iv({dialysis:'none',aki:false,...o});
assert.equal(iv({egfr:29.9}).level,'high');assert.equal(iv({egfr:30}).level,'intermediate');assert.equal(iv({egfr:44.9}).level,'intermediate');assert.equal(iv({egfr:45}).level,'low');
assert.equal(iv({egfr:90,aki:true}).level,'high');assert.equal(iv({aki:true}).level,'high');assert.equal(iv({egfr:''}).ok,false);
assert.equal(iv({dialysis:'anuric'}).level,'none');assert.equal(iv({dialysis:'nonanuric'}).level,'high');assert.match(iv({dialysis:'nonanuric'}).advice.join(' '),/not indicated/);
assert.ok(html.includes(read('./dist/contrast-math.js'))&&html.includes(read('./dist/contrast-calculator.js'))&&/id="contrast-calculator"/.test(html));
assert.ok(!/localStorage|sessionStorage|fetch\s*\(|downloadText|setHash|location\./.test(read('./dist/contrast-math.js')+read('./dist/contrast-calculator.js')),'Contrast calculator values must not be persisted, exported or sent');
// PREVENT (Khan et al. 2024): base and base+UACR models, 10- and 30-year; reference outputs published with the preventr package tests (CRAN 0.12.2).
vm.runInContext(read('./dist/prevent-math.js')+';this.PV=PreventMath;',context);const PV=context.PV;
const pv=o=>PV.compute({age:50,sbp:160,bpTx:true,tc:200,hdl:45,statin:false,dm:true,smoking:false,egfr:90,bmi:35,cholUnit:'mgdl',uacr:'',...o});
const r3=v=>Math.round(v*1000)/1000,trio=o=>[r3(o.total_cvd),r3(o.ascvd),r3(o.heart_failure)];
for(const [o,ten,thirty] of [[{sex:'female'},[0.147,0.092,0.081],[0.53,0.354,0.39]],[{sex:'female',uacr:92},[0.181,0.111,0.105],[0.565,0.381,0.437]],[{sex:'male'},[0.163,0.102,0.106],[0.514,0.349,0.424]],[{sex:'male',uacr:92},[0.195,0.123,0.13],[0.535,0.368,0.448]]]){
  const a=pv(o);assert.equal(a.ok,true);assert.equal(a.model,o.uacr?'uacr':'base');assert.deepEqual(trio(a.tenYear),ten,JSON.stringify(o));assert.deepEqual(trio(a.thirtyYear),thirty,JSON.stringify(o));}
const mm=pv({sex:'female',tc:200*0.02586,hdl:45*0.02586,cholUnit:'mmol'});assert.ok(Math.abs(mm.tenYear.total_cvd-pv({sex:'female'}).tenYear.total_cvd)<1e-12);
assert.ok(Math.abs(pv({sex:'male',uacr:92/8.84,uacrUnit:'mgmmol'}).tenYear.total_cvd-pv({sex:'male',uacr:92}).tenYear.total_cvd)<1e-12);
assert.equal(pv({sex:'male',age:60}).thirtyYear,null);assert.ok(pv({sex:'male',age:59}).thirtyYear);
for(const bad of [{sex:''},{sex:'female',age:29},{sex:'female',age:80},{sex:'female',tc:129},{sex:'female',hdl:101},{sex:'female',sbp:89},{sex:'female',sbp:181},{sex:'female',bmi:40},{sex:'female',egfr:14},{sex:'female',egfr:141},{sex:'female',uacr:-1},{sex:'female',tc:9,cholUnit:'mmol'}]){const x=pv(bad);assert.equal(x.ok,false,JSON.stringify(bad));assert.equal('tenYear' in x,false);}
assert.ok(html.includes(read('./dist/prevent-math.js'))&&html.includes(read('./dist/prevent-calculator.js'))&&/id="prevent-calculator"/.test(html)&&/id="calc-menu"/.test(html));
assert.match(html,/class="calculator-launch" data-open="calc-menu"[^>]*>CALC</);
assert.ok(!/localStorage|sessionStorage|fetch\s*\(|downloadText|setHash|location\./.test(read('./dist/prevent-math.js')+read('./dist/prevent-calculator.js')),'PREVENT values must not be persisted, exported or sent');
// CKD risk, KFRE, body size, dialysis adequacy.
vm.runInContext(read('./dist/kidney-tools-math.js')+';this.KT=KidneyTools;',context);const KT=context.KT;
const grid={G1:['low','moderate','high'],G2:['low','moderate','high'],G3a:['moderate','high','very high'],G3b:['high','very high','very high'],G4:['very high','very high','very high'],G5:['very high','very high','very high']};
for(const [egfr,g] of [[95,'G1'],[90,'G1'],[89.9,'G2'],[60,'G2'],[59,'G3a'],[45,'G3a'],[44,'G3b'],[30,'G3b'],[29,'G4'],[15,'G4'],[14,'G5']])for(const [acr,a,i] of [[29.9,'A1',0],[30,'A2',1],[300,'A2',1],[301,'A3',2]]){const x=KT.ckd({egfr,acr,acrUnit:'mgg'});assert.equal(x.g,g);assert.equal(x.a,a);assert.equal(x.risk,grid[g][i],`${egfr}/${acr}`);}
assert.equal(KT.ckd({egfr:70,acr:3.4,acrUnit:'mgmmol'}).a,'A2');assert.equal(KT.ckd({egfr:70,acr:3.39,acrUnit:'mgmmol'}).a,'A1');
// KFRE against the LOINC 85624-5 / 85625-2 formula written out independently; non-North American S0 = 1 − (1 − S0_NA) × (1 − 0.329) and × (1 − 0.165) (JAMA 2016 recalibration).
const loinc=(s0,age,male,egfr,acr)=>1-Math.pow(s0,Math.exp(-0.2201*(age/10-7.036)+0.2467*(male-0.5642)-0.5567*(egfr/5-7.222)+0.4510*(Math.log(acr)-5.137)));
assert.ok(Math.abs(1-(1-0.9750)*(1-0.329)-0.9832)<5e-5&&Math.abs(1-(1-0.9240)*(1-0.165)-0.9365)<5e-5);
for(const [age,sex,egfr,acr] of [[70,'male',25,300],[55,'female',40,50],[80,'female',18,1200],[45,'male',55,10]]){const m=sex==='male'?1:0;
  const na=KT.ckd({egfr,acr,acrUnit:'mgg',age,sex,region:'NA'}).kfre,nn=KT.ckd({egfr,acr,acrUnit:'mgg',age,sex,region:'nonNA'}).kfre;
  assert.ok(Math.abs(na.two-loinc(0.9750,age,m,egfr,acr))<1e-12&&Math.abs(na.five-loinc(0.9240,age,m,egfr,acr))<1e-12);assert.ok(Math.abs(nn.two-loinc(0.9832,age,m,egfr,acr))<1e-12&&nn.five<na.five);}
assert.equal(KT.ckd({egfr:75,acr:500,acrUnit:'mgg',age:60,sex:'male'}).kfre,null);assert.equal(KT.ckd({egfr:40,acr:500,acrUnit:'mgg'}).kfre,null);
for(const bad of [{egfr:'',acr:30},{egfr:40,acr:0},{egfr:250,acr:30}])assert.equal(KT.ckd(bad).ok,false);
// Body size: Mosteller 180 cm/80 kg = 2.00 m²; Devine IBW 175 cm male = 70.46 kg.
const bd=KT.body({height:180,weight:80,sex:'male'});assert.ok(Math.abs(bd.bsa-2)<1e-12&&Math.abs(bd.bmi-24.691358)<1e-6&&bd.cls==='Healthy weight');
assert.ok(Math.abs(KT.body({height:175,weight:90,sex:'male'}).ibw-(50+2.3*(175/2.54-60)))<1e-9);assert.equal(KT.body({height:175,weight:60,sex:'male'}).adj,null);
for(const [w,c] of [[56.6,'Underweight'],[75,'Healthy weight'],[90,'Overweight'],[100,'Obesity class I'],[115,'Obesity class II'],[130,'Obesity class III']])assert.equal(KT.body({height:175,weight:w}).cls,c,String(w));
// Dialysis: hand-calculated Daugirdas examples.
const dl=KT.dialysis({pre:100,post:30,hours:4,uf:3,weight:70});assert.ok(Math.abs(dl.ktv-(-Math.log(0.3-0.032)+(4-1.05)*3/70))<1e-12&&Math.abs(dl.urr-0.7)<1e-12);
assert.ok(Math.abs(KT.dialysis({pre:70,post:20,hours:4,uf:3,weight:70}).ktv-1.5)<0.002);
for(const bad of [{pre:70,post:80,hours:4,uf:2,weight:70},{pre:70,post:20,hours:0.5,uf:2,weight:70},{pre:70,post:20,hours:4,uf:-1,weight:70}])assert.equal(KT.dialysis(bad).ok,false);
assert.ok(html.includes(read('./dist/kidney-tools-math.js'))&&html.includes(read('./dist/kidney-tools.js')));
for(const id of ['ckd-calculator','body-calculator','dialysis-calculator'])assert.match(html,new RegExp(`data-open="${id}"`));
assert.ok(!/localStorage|sessionStorage|fetch\s*\(|downloadText|setHash|location\./.test(read('./dist/kidney-tools-math.js')+read('./dist/kidney-tools.js')));
console.log('PASS: NKF Table S1 reference cases in both units; independent MDRD examples; splice, BSA and validation cases; retained calculator sources; embedded calculator and no persistence/export/network path; Mehran points/bands and ACR–NKF IV thresholds for the contrast-AKI panel; PREVENT base/UACR 10- and 30-year reference outputs and the CALC menu; KDIGO grid, KFRE, body-size and Kt/V cases.');
